Author:     Richard Marti <richard.marti@gmail.com>
AuthorDate: Fri Jul 18 10:48:09 2025 +1200
Commit:     Richard Marti <richard.marti@gmail.com>
CommitDate: Fri Jul 18 10:48:09 2025 +1200

    Bug 1977033 - Port M-C titlebar caption button changes. r=aleca,melissa_a


    Bug 1439374 - [CSD] Can’t drag by the close button.
    Bug 1974861 - GTK Titlebar Buttons / Window Controls Display Incorrectly.
    Bug 1974984 - Consider tweaking Breeze titlebar buttons to match better the default KDE style.

    Differential Revision: https://phabricator.services.mozilla.com/D257096

diff --git a/mail/themes/linux/mail/messenger.css b/mail/themes/linux/mail/messenger.css
index 6acefa63647..b968c231629 100644
--- a/mail/themes/linux/mail/messenger.css
+++ b/mail/themes/linux/mail/messenger.css
@@ -122,6 +122,23 @@
   position: relative;
   z-index: 1;
   align-items: stretch;
+  /* In libadwaita buttons are 24px big and spacing is
+   * 3px of gap + 5px * 2 of padding = 13px / 2, see:
+   * https://gitlab.gnome.org/GNOME/libadwaita/-/blob/fe21c3c823443a8f2333cf3cc09ba3d0fa753228/src/stylesheet/widgets/_header-bar.scss#L164
+   * We want a contiguous hit region so we use 6.5px of padding instead. */
+  --titlebar-button-size: 24px;
+  --titlebar-button-spacing: 6.5px;
+  --titlebar-button-end-spacing: 10px;
+  @media (-moz-gtk-theme-family: breeze) {
+    --titlebar-button-size: 18px;
+    --titlebar-button-spacing: 3px;
+    --titlebar-button-end-spacing: 10px;
+  }
+  --max-titlebar-button-position: max(
+    env(-moz-gtk-csd-maximize-button-position),
+    env(-moz-gtk-csd-minimize-button-position),
+    env(-moz-gtk-csd-close-button-position)
+  );
 }

 .titlebar-button {
@@ -129,7 +146,16 @@
   color: inherit;
   align-items: center;
   padding: 0;
-  padding-inline: calc(env(-moz-gtk-csd-titlebar-button-spacing) / 2);
+  padding-inline: var(--titlebar-button-spacing);
+  padding-inline-end: max(
+    var(--titlebar-button-spacing),
+    var(--titlebar-button-end-spacing) *
+    (var(--titlebar-button-position) -
+    var(--max-titlebar-button-position) + 1)
+  );
+  order: var(--titlebar-button-position);
+  /* In GTK applications, you can drag the window by titlebar buttons */
+  -moz-window-dragging: drag;

   > .toolbarbutton-icon {
     appearance: auto;
@@ -138,11 +164,18 @@
     background-repeat: no-repeat;
     -moz-context-properties: stroke;
     stroke: currentColor;
-    /* Roughly the Adwaita size */
-    width: 24px;
-    height: 24px;
-    /* Matches the libadwaita transition */
-    transition: background-color .2s ease;
+    width: var(--titlebar-button-size);
+    height: var(--titlebar-button-size);
+
+    @media not (-moz-gtk-theme-family: breeze) {
+      /* Matches the libadwaita transition */
+      transition: background-color .2s ease;
+    }
+
+    @media (-moz-gtk-theme-family: adwaita) or (-moz-gtk-theme-family: yaru) {
+      /* On Adwaita / Yaru, the titlebar buttons have a background by default */
+      background-color: color-mix(in srgb, currentColor 10%, transparent);
+    }
   }

   &:hover > .toolbarbutton-icon {
@@ -157,10 +190,30 @@
     outline: var(--focus-outline);
     outline-offset: var(--focus-outline-inset);
   }
+
+  @media (-moz-gtk-theme-family: breeze) {
+    &:hover > .toolbarbutton-icon {
+      color: var(--toolbox-bgcolor);
+      background-color: var(--toolbox-textcolor);
+      &:-moz-window-inactive {
+        color: var(--toolbox-bgcolor-inactive);
+        background-color: var(--toolbox-textcolor-inactive);
+      }
+    }
+    &:hover:active > .toolbarbutton-icon {
+      background-color: color-mix(in srgb, var(--toolbox-textcolor) 50%, transparent);
+    }
+    &.titlebar-close:hover > .toolbarbutton-icon {
+      background-color: #ff98a2;
+    }
+    &.titlebar-close:hover:active > .toolbarbutton-icon {
+      background-color: #6d2229;
+    }
+  }
 }

 .titlebar-min {
-  order: env(-moz-gtk-csd-minimize-button-position);
+  --titlebar-button-position: env(-moz-gtk-csd-minimize-button-position);

   > .toolbarbutton-icon {
     background-image: -moz-symbolic-icon(window-minimize-symbolic);
@@ -171,31 +224,25 @@
   }
 }

-.titlebar-max {
-  order: env(-moz-gtk-csd-maximize-button-position);
+.titlebar-max,
+.titlebar-restore {
+  --titlebar-button-position: env(-moz-gtk-csd-maximize-button-position);

   > .toolbarbutton-icon {
     background-image: -moz-symbolic-icon(window-maximize-symbolic);
   }
-}
-
-.titlebar-restore {
-  order: env(-moz-gtk-csd-maximize-button-position);

-  > .toolbarbutton-icon {
-    background-image: -moz-symbolic-icon(window-restore-symbolic);
+  @media not (-moz-gtk-csd-maximize-button) {
+    display: none;
   }
 }

-@media not (-moz-gtk-csd-maximize-button) {
-  .titlebar-max,
-  .titlebar-restore {
-    display: none;
-  }
+.titlebar-restore > .toolbarbutton-icon {
+  background-image: -moz-symbolic-icon(window-restore-symbolic);
 }

 .titlebar-close {
-  order: env(-moz-gtk-csd-close-button-position);
+  --titlebar-button-position: env(-moz-gtk-csd-close-button-position);

   > .toolbarbutton-icon {
     background-image: -moz-symbolic-icon(window-close-symbolic);
diff --git a/mail/themes/linux/mail/variables.css b/mail/themes/linux/mail/variables.css
index 3b5a81d4f6b..21087dd114f 100644
--- a/mail/themes/linux/mail/variables.css
+++ b/mail/themes/linux/mail/variables.css
@@ -10,4 +10,17 @@
   --row-grouped-header-bg-color: -moz-dialog;
   --row-grouped-header-bg-color-selected: var(--selected-item-color);
   --autocomplete-popup-url-color: LinkText;
+
+  /* Used for Breeze titlebar-button buttons */
+  --toolbox-bgcolor: -moz-headerbar;
+  --toolbox-textcolor: -moz-headerbartext;
+  --toolbox-bgcolor-inactive: -moz-headerbarinactive;
+  --toolbox-textcolor-inactive: -moz-headerbarinactivetext;
+
+  &[lwtheme] {
+    --toolbox-bgcolor: var(--lwt-accent-color);
+    --toolbox-bgcolor-inactive: var(--lwt-accent-color-inactive, var(--lwt-accent-color));
+    --toolbox-textcolor: var(--lwt-text-color, currentColor);
+    --toolbox-textcolor-inactive: var(--lwt-text-color, currentColor);
+  }
 }
